🐛 Describe the bug
torch.export emits torch.ops.aten.log_sigmoid_forward.default which is not part of the Core ATen IR.
import torch

class Model(torch.nn.Module):
    def __init__(self):
        super().__init__()
        self.m = torch.nn.LogSigmoid()
    def forward(self, x):
        return self.m(x)
input = torch.randn(2)

ep = torch.export.export(Model(), args=(input,))
ep.graph_module.graph.print_tabular()
ep.graph_module.print_readable()
The logs shows the unexpected presence of aten.log_sigmoid_forward.default
[2023-10-30 18:52:56,878] [INFO] [real_accelerator.py:110:get_accelerator] Setting ds_accelerator to cuda (auto detect)
opcode         name                 target                            args                      kwargs
-------------  -------------------  --------------------------------  ------------------------  --------
placeholder    arg0_1               arg0_1                            ()                        {}
call_function  log_sigmoid_forward  aten.log_sigmoid_forward.default  (arg0_1,)                 {}
call_function  getitem              <built-in function getitem>       (log_sigmoid_forward, 0)  {}
output         output               output                            ((getitem,),)             {}
class GraphModule(torch.nn.Module):
    def forward(self, arg0_1: f32[2]):
        # File: test_log_sigmoid.py:9, code: return self.m(x)
        log_sigmoid_forward = torch.ops.aten.log_sigmoid_forward.default(arg0_1);  arg0_1 = None
        getitem: f32[2] = log_sigmoid_forward[0];  log_sigmoid_forward = None
        return (getitem,)
